$('romMode').onclick=()=>pup.setMode('rom');
const bases={amber:[255,135,36],green:[105,255,139],ice:[85,204,255],gray:[240,242,255]};
function message(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error)}
function makeDemo(){const glyphs={'V':['10001','10001','10001','10001','10001','01010','00100'],'W':['10001','10001','10001','10101','10101','10101','01010'],'A':['01110','10001','10001','11111','10001','10001','10001'],'B':['11110','10001','10001','11110','10001','10001','11110'],'D':['11110','10001','10001','10001','10001','10001','11110'],'E':['11111','10000','10000','11110','10000','10000','11111'],'I':['111','010','010','010','010','010','111'],'L':['10000','10000','10000','10000','10000','10000','11111'],'M':['10001','11011','10101','10101','10001','10001','10001'],'O':['01110','10001','10001','10001','10001','10001','01110'],'P':['11110','10001','10001','11110','10000','10000','10000'],'R':['11110','10001','10001','11110','10100','10010','10001'],'S':['01111','10000','10000','01110','00001','00001','11110'],'T':['11111','00100','00100','00100','00100','00100','00100'],'Y':['10001','10001','01010','00100','00100','00100','00100'],' ':['000','000','000','000','000','000','000'],"'":['1','1','0','0','0','0','0']};
const text=(data,str,y,value)=>{const width=[...str].reduce((a,c)=>a+glyphs[c][0].length+1,0)-1;let x=Math.floor((128-width)/2);for(const c of str){const g=glyphs[c];g.forEach((row,dy)=>[...row].forEach((b,dx)=>{if(b==='1')data[(y+dy)*128+x+dx]=value}));x+=g[0].length+1}};
const create=(name,kind)=>({name,w:128,h:32,demo:true,frames:Array.from({length:120},(_,f)=>{const data=new Uint8Array(4096);if(kind===0){for(let x=3;x<125;x++){data[3*128+x]=4;data[28*128+x]=4}text(data,"DMD VIEWER",8,15);text(data,'PRESS PLAY',19,Math.floor(f/20)%2?7:12);const x=3+f%122;data[3*128+x]=15;data[28*128+127-x]=15}else if(kind===1){for(let y=0;y<32;y++)for(let x=0;x<128;x++)data[y*128+x]=Math.floor(((x+f)%128)/8)}else{for(let y=0;y<32;y++)for(let x=0;x<128;x++)data[y*128+x]=Math.hypot(x-(f*1.3%128),y-16)<8?15:((x+y)%8===0?2:0)}return {data,levels:16,delay:1000/30}})});
return [create('Attract mode',0),create('Grayscale ramp',1),create('Moving dot test',2)]}
function getColors(){const val=$('palette').value;if(val==='embedded'&&scene.colors)return scene.colors;if(val.startsWith('pal:'))return palettes[+val.slice(4)].colors;const base=bases[val]||bases.amber;return Array.from({length:256},(_,i)=>base.map(c=>Math.round(c*i/255)))}
function colorAt(value,levels,colors){return colors[Math.min(colors.length-1,Math.round(value/(levels-1)*(colors.length-1)))]||[0,0,0]}
function swatches(){const colors=getColors();$('swatches').replaceChildren(...Array.from({length:16},(_,i)=>{const s=document.createElement('span');s.style.background='rgb('+colorAt(i,16,colors)+')';return s}))}
function formatTime(ms){return String(Math.floor(ms/60000)).padStart(2,'0')+':'+(ms/1000%60).toFixed(3).padStart(6,'0')}
function draw(){if(!scene)return;const frame=scene.frames[index],w=scene.w,h=scene.h,scale=8,brightness=+$('brightness').value/100,colors=getColors(),dots=$('dots').checked;canvas.width=w*scale;canvas.height=h*scale;canvas.style.aspectRatio=w+'/'+h;ctx.fillStyle='#090a0a';ctx.fillRect(0,0,canvas.width,canvas.height);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const p=y*w+x;const c=(frame.rgb?[...frame.data.subarray(p*3,p*3+3)]:colorAt(frame.data[p],frame.levels,colors)).map(v=>Math.round(v*brightness));ctx.fillStyle='rgb('+c.map(v=>Math.max(12,v))+')';if(dots){ctx.beginPath();ctx.arc(x*8+4,y*8+4,3.05,0,Math.PI*2);ctx.fill()}else ctx.fillRect(x*8,y*8,8,8)}canvas.style.filter=$('glow').checked?'drop-shadow(0 0 5px '+(frame.rgb?'#a44a2525':'#e8732028')+')':'none';$('timeline').value=index;$('time').textContent=formatTime(scene.frames.slice(0,index).reduce((t,f)=>t+f.delay,0));$('frameInfo').textContent='FRAME '+String(index+1).padStart(3,'0')+' / '+scene.frames.length;$('statDelay').innerHTML=Math.round(frame.delay)+' <em>ms</em>';$('depthInfo').textContent=frame.rgb?'RGB888 Â· TRUE COLOR':Math.log2(frame.levels)+'-BIT Â· '+frame.levels+' COLORS'}
const controlIcons={play:'<path d="m8 5 11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',restart:'<path d="M3 10a9 9 0 1 1 1.7 7M3 4v6h6"/>',previous:'<path d="M6 5v14m13-14L9 12l10 7z"/>',next:'<path d="M18 5v14M5 5l10 7-10 7z"/>',loop:'<path d="m17 2 4 4-4 4M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4m14-1v2a3 3 0 0 1-3 3H3"/>'};
function icon(name){return '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">'+controlIcons[name]+'</svg>'}
function updatePlay(){const label=playing?'Pause':'Play';$('play').innerHTML=icon(playing?'pause':'play');$('play').setAttribute('aria-label',label);$('play').title=label+' (Space)';$('play').setAttribute('aria-pressed',String(playing));$('playState').textContent=playing?'PLAYING':'PAUSED'}
function togglePlayback(){if(!playing&&index===scene.frames.length-1){index=0;elapsed=0;draw()}playing=!playing;last=0;updatePlay()}
function restart(){index=0;elapsed=0;last=0;draw()}

function selectScene(s){$('sceneNote').textContent=s.partial?'Stored color planes only. This scene needs original game frames for its complete appearance.':s.mode!==undefined?'Standalone scene Â· using palette '+s.paletteId:'';scene=s;index=0;elapsed=0;last=0;$('animationInfo').textContent='ANIMATION '+String(scenes.indexOf(s)+1).padStart(3,'0')+' / '+scenes.length;$('displayName').textContent=s.name;$('sourceBadge').textContent=s.demo?'DEMO':s.sourceType;$('resolution').textContent=s.w+' Ã— '+s.h;$('statDim').innerHTML=s.w+' <em>Ã—</em> '+s.h;$('timeline').max=s.frames.length-1;$('duration').textContent=formatTime(s.frames.reduce((t,f)=>t+f.delay,0));const existing=$('palette').querySelector('[value=embedded]');if(existing)existing.remove();if(s.colors){$('palette').add(new Option('Scene colors','embedded'));$('palette').value='embedded'}else {const p=palettes.findIndex(p=>p.id===s.paletteId);if(p>=0)$('palette').value='pal:'+p;else if($('palette').value==='')$('palette').value='amber'}renderScenes();swatches();draw();if(s.mode!==undefined)message(s.sourceType+' '+(s.partial?'stored-plane preview: this scene requires source game frames for its complete appearance.':'replacement animation: standalone playback.')+' Palette '+s.paletteId+' Â· offset '+s.offset)}
function filteredScenes(){const q=$('search').value.toLowerCase();return scenes.filter(s=>s.name.toLowerCase().includes(q)&&($('sceneFilter').value==='all'||($('sceneFilter').value==='partial'?s.partial:!s.partial)))}
function renderScenes(){$('sceneCount').textContent=scenes.length;$('scenes').replaceChildren(...filteredScenes().map(s=>{const b=document.createElement('button');b.className='scene'+(s===scene?' active':'');b.setAttribute('aria-pressed',s===scene);const num=document.createElement('span');num.className='num';num.textContent=String(scenes.indexOf(s)+1).padStart(2,'0');const name=document.createElement('span');name.className='scene-name';name.textContent=s.name;const small=document.createElement('small');small.textContent=s.frames.length+'f';b.append(num,name,small);b.onclick=()=>selectScene(s);return b}))}
function renderFiles(){$('fileCount').textContent=sources.length+' FILE'+(sources.length===1?'':'S');$('files').replaceChildren(...sources.map(f=>{const div=document.createElement('div');div.className='file-item';const icon=document.createElement('span');icon.className='file-icon';icon.textContent=f.type;const info=document.createElement('div'),strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=f.name;small.textContent=f.note;info.append(strong,small);div.append(icon,info);return div}))}
async function load(files,{replace=false}={}){const selected=Array.from(files);if(selected.some(f=>/\.zip$/i.test(f.name))&&selected.some(f=>/\.pac$/i.test(f.name))&&!selected.some(f=>/\.pup$/i.test(f.name))){const ready=await rom.accept(selected);$('fileInput').value='';return ready}let failed=false;try{files=await pup.accept([...files]);if(files.length)pup.setMode('dmd')}catch(e){message(e.message,true);$('fileInput').value='';return false}for(const file of [...files].sort((a,b)=>Number(b.name.toLowerCase().endsWith('.pal'))-Number(a.name.toLowerCase().endsWith('.pal')))){try{if(file.size>64*1024*1024)throw Error('Maximum file size is 64 MB');if(!replace&&totalLoaded+file.size>128*1024*1024)throw Error('Session limit reached. Reload to clear loaded files.');let bytes=new Uint8Array(await file.arrayBuffer()),type=file.name.split('.').pop().toLowerCase();if(type==='zip'){const entries=await extractDmdZip(bytes);if(!await load(entries.map(entry=>new File([entry.data],entry.name))))throw Error('The ZIP display pair could not be loaded. Verify that PAL and animation files match.');playing=true;updatePlay();message('Opened '+file.name+' Â· '+entries.length+' display files');continue}if(type==='gz'){const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));const reader=stream.getReader(),chunks=[];let length=0;while(true){const {done,value}=await reader.read();if(done)break;length+=value.length;if(length>64*1024*1024){await reader.cancel();throw Error('Decompressed dump exceeds 64 MB')}chunks.push(value)}bytes=new Uint8Array(length);let off=0;for(const c of chunks){bytes.set(c,off);off+=c.length}type='txt'}let note;if(type==='pac'){pendingPac=file;const decoded=await parsePac(bytes,$('pacKey').value);if(replace){palettes=[];scenes=[];sources=[];currentPal=null;totalLoaded=0;for(const option of [...$('palette').options])if(option.value.startsWith('pal:')||option.value==='embedded')option.remove()}const start=palettes.length;palettes.push(...decoded.palettes);decoded.palettes.forEach((p,i)=>$('palette').add(new Option('PAC palette '+p.id,'pal:'+(start+i))));if(decoded.scenes.length){if(scenes.every(s=>s.demo))scenes=[];decoded.scenes.forEach(s=>s.sourceType='PAC');scenes.push(...decoded.scenes);selectScene(decoded.scenes[0])}else {$('palette').value='pal:'+start;swatches();draw()}playing=false;updatePlay();pendingPac=null;note=decoded.scenes.length+' animations Â· '+decoded.palettes.length+' palettes'}else if(type==='pal'){const p=parsePalMappings(bytes),start=palettes.length;currentPal=p;palettes.push(...p.palettes);p.palettes.forEach((p,i)=>$('palette').add(new Option('PAL '+p.id+' Â· '+file.name,'pal:'+(start+i))));$('palette').value='pal:'+(start+Math.max(0,p.palettes.findIndex(p=>p.default)));note=p.palettes.length+' palettes Â· v'+p.version;swatches();draw()}else{let incoming;if(type==='fsq')incoming=parseFsq(bytes,currentPal);else if(type==='vni')incoming=parseVni(bytes);else if(type==='txt')incoming=parseDump(new TextDecoder().decode(bytes));else if(['raw','bin'].includes(type)){const [w,h]=$('rawSize').value.split(',').map(Number);incoming=parseRaw(bytes,w,h,$('rawLayout').value)}else throw Error(type.toUpperCase()+' decoding is not available. Use VNI, PAL, a TXT/GZ dump, or headerless RAW. Game ROMs require a pinball emulator.');if(scenes.every(s=>s.demo))scenes=[];incoming.forEach(s=>{s.sourceType=type.toUpperCase();s.source=file.name});scenes.push(...incoming);note=incoming.length+' animation'+(incoming.length===1?'':'s')+' Â· '+incoming.reduce((n,s)=>n+s.frames.length,0)+' frames';selectScene(incoming[0]);playing=false;updatePlay()}sources.push({name:file.name,type:type.toUpperCase(),note});totalLoaded+=file.size;renderFiles();message('Loaded '+file.name+' Â· '+note)}catch(e){failed=true;message(file.name+': '+e.message,true)}}$('fileInput').value='';return !failed}
$('open').onclick=$('drop').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>load(e.target.files);document.addEventListener('dragover',e=>{e.preventDefault();$('drop').classList.add('drag')});document.addEventListener('dragleave',e=>{if(!e.relatedTarget)$('drop').classList.remove('drag')});document.addEventListener('drop',e=>{e.preventDefault();$('drop').classList.remove('drag');load(e.dataTransfer.files)});
function step(delta){playing=false;updatePlay();index=Math.max(0,Math.min(scene.frames.length-1,index+delta));elapsed=0;draw()}
$('play').onclick=togglePlayback;$('prev').onclick=()=>step(-1);$('next').onclick=()=>step(1);$('first').onclick=restart;$('loop').onclick=()=>{loop=!loop;$('loop').classList.toggle('active',loop);$('loop').setAttribute('aria-pressed',loop)};$('timeline').oninput=e=>{playing=false;updatePlay();index=+e.target.value;elapsed=0;draw()};$('search').oninput=renderScenes;$('sceneFilter').onchange=()=>{renderScenes();if($('playAll').checked&&!filteredScenes().includes(scene))changeScene(1)};
function changeScene(direction){const visible=filteredScenes();if(!visible.length)return;const pos=visible.indexOf(scene);for(let distance=1;distance<=visible.length;distance++){const next=visible[pos<0?(direction>0?distance-1:visible.length-distance):(pos+direction*distance+visible.length*2)%visible.length];if(next===scene)continue;if(scene.offset!==undefined&&next.offset===scene.offset&&next.source===scene.source)continue;selectScene(next);return true}return false;}
$('prevScene').onclick=()=>changeScene(-1);$('nextScene').onclick=()=>changeScene(1);
for(const id of ['brightness','dots','glow','palette'])$(id).oninput=()=>{$('brightnessValue').textContent=$('brightness').value+'%';swatches();draw()};$('help').onclick=()=>$('guide').showModal();$('closeGuide').onclick=()=>$('guide').close();$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('screenWrap').requestFullscreen()}catch{message('Fullscreen is unavailable in this embedded browser. Open the site in Chrome for fullscreen.',true)}};
$('snapshot').onclick=()=>{const a=document.createElement('a');a.download='dmd-frame-'+(index+1)+'.png';a.href=canvas.toDataURL('image/png');a.click();message('Saved frame '+(index+1)+' as PNG')};
canvas.onmousemove=e=>{const rect=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-rect.left)/rect.width*scene.w),y=Math.floor((e.clientY-rect.top)/rect.height*scene.h);if(x<0||y<0||x>=scene.w||y>=scene.h)return;const f=scene.frames[index],p=y*scene.w+x;$('pixelPos').textContent=x+', '+y;$('pixelValue').textContent=f.rgb?[...f.data.subarray(p*3,p*3+3)].join(','):f.data[p]};canvas.onmouseleave=()=>{$('pixelPos').textContent='Hover display';$('pixelValue').textContent='â€”'};
document.addEventListener('keydown',e=>{
  const target=document.activeElement;
  if(!$('pupPanel').hidden||!$('romPanel').hidden||['INPUT','SELECT','TEXTAREA'].includes(target?.tagName)||target?.isContentEditable||$('guide').open||e.ctrlKey||e.metaKey)return;
  if(e.code==='Space'){e.preventDefault();if(!e.repeat)togglePlayback();return}
  if(e.code==='ArrowLeft'||e.code==='ArrowRight'){e.preventDefault();const direction=e.code==='ArrowLeft'?-1:1;if(e.altKey){if(!e.repeat)changeScene(direction)}else step(direction);return}
  if(e.code==='Home'){e.preventDefault();restart()}
});
for(const [id,name] of [['first','restart'],['prev','previous'],['next','next'],['loop','loop']])$(id).innerHTML=icon(name);

function tick(t){if(!last)last=t;const dt=Math.min(t-last,250);last=t;if(playing&&scene){elapsed+=dt*+$('speed').value;let changed=false,n=0;while(elapsed>=scene.frames[index].delay&&n++<1000){elapsed-=scene.frames[index].delay;if(index===scene.frames.length-1){if($('playAll').checked){changeScene(1);changed=true;break}else if(loop)index=0;else {playing=false;elapsed=0;updatePlay();break}}else index++;changed=true}if(changed)draw()}requestAnimationFrame(tick)}
scenes=makeDemo();sources=[{name:'Built-in display tests',type:'DEMO',note:'3 animations Â· 128 Ã— 32'}];renderFiles();selectScene(scenes[0]);updatePlay();requestAnimationFrame(tick);

$('retryPac').onclick=()=>{if(pendingPac){$('guide').close();load([pendingPac])}else message('Choose a PAC file with Open files after entering the key.')};

if(new URLSearchParams(location.search).has('localPair')){(async()=>{try{const response=await fetch('/__local__/manifest.json');if(!response.ok)throw Error('Local pair is unavailable');const manifest=await response.json();const files=await Promise.all(manifest.map(async item=>{const r=await fetch(item.url);if(!r.ok)throw Error('Could not load '+item.name);return new File([await r.arrayBuffer()],item.name)}));await load(files);const ready=scenes.find(s=>s.mode===1&&s.frames.length>20);if(ready)selectScene(ready);playing=$('pupPanel').hidden;updatePlay()}catch(e){message(e.message,true)}})()}

function includedMessage(text,error=false){message(text,error);$('includedStatus').hidden=false;$('includedStatus').textContent=text;$('includedStatus').classList.toggle('error',error)}
let loadedGame=null;
$('advancedTools').onclick=()=>{const open=$('advancedTools').getAttribute('aria-expanded')!=='true';document.body.classList.toggle('simple-player',!open);$('advancedTools').setAttribute('aria-expanded',String(open));$('advancedTools').textContent=open?'Hide advanced tools':'Advanced tools';if(!open)pup.setMode('rom')};
async function playIncludedGame({autostart=true}={}){
  const select=$('includedGame'),button=$('loadIncludedGame'),id=select.value;
  if(!id)return;
  select.disabled=true;button.disabled=true;button.textContent='Loadingâ€¦';
  try{
    // Unlock during the dropdown/button gesture, before any network requests.
    if(autostart)await rom.prepareAudio();
    if(!globalThis.crossOriginIsolated){
      pup.setMode('rom');includedMessage('Preparing the player. This page will reload onceâ€¦');
      $('romEnable').click();return;
    }
    pup.setMode('rom');
    if(loadedGame!==id){
      rom.stop();loadedGame=null;includedMessage('Loading game, color display, and soundâ€¦');
      const {game,files}=await fetchIncludedRomGame(id);
      if(!await rom.accept(files))throw Error($('romStatus').textContent);
      loadedGame=id;includedMessage(game.title+' is ready. Press Play game to start with sound.');
    }
    if(autostart){rom.stop();await rom.start();if($('romStatus').classList.contains('error'))throw Error($('romStatus').textContent);includedMessage('Starting '+includedGames.find(game=>game.id===id).title+' with live color DMD'+($('includedSound').checked?' and sound.':'.'));}
  }catch(error){includedMessage(error.message,true)}finally{select.disabled=false;button.disabled=!select.value;button.textContent='Play game'}
}
$('includedGame').onchange=()=>{if(!$('includedGame').value){rom.stop();loadedGame=null;$('loadIncludedGame').disabled=true;return}return playIncludedGame()};
$('loadIncludedGame').onclick=()=>playIncludedGame();
const includedId=new URLSearchParams(location.search).get('game');
// The isolated page reload cannot preserve the browser's audio gesture.
// Prepare the selected pair, then leave one clear Play button for sound.
if(includedGames.some(game=>game.id===includedId)){$('includedGame').value=includedId;playIncludedGame({autostart:false})}
else if(document.body?.classList.contains('simple-player'))pup.setMode('rom');
